    kazgenre_explain: "Барыс қазақ тіліндегі әртүрлі жанрдағы мәтіндерді ажыратуды үйренеді! Өлеңнің, ертегінің және жұмбақтың — әрқайсысының өз ерекшелігі бар. Сипаттаманы оқы да, бұл жанр қазақша қалай аталатынын тап. Дайынсың ба?",
    kazgenre_game_title: "Бұл қандай жанр?",
    kazgenre_game_sub: "Мұнда қай жанр сипатталған?",
    kazgenre_desc_poem: "Жолдары бір-бірімен ұйқасатын мәтін",
    kazgenre_desc_tale: "Сиқыры бар оқиға, онда көбіне жақсылық жамандықты жеңеді",
    kazgenre_desc_riddle: "Не туралы айтылғанын табу керек қысқа мәтін",
    kazgenre_poem: "Өлең",
    kazgenre_tale: "Ертегі",
    kazgenre_riddle: "Жұмбақ",
    kazakh_q3_note: "Осы тоқсанның қалған тақырыптары нағыз ауызша сөйлеуді талап етеді — батырма ойындарына айналдырылмайды",
    qwords_game_title: "Сұрау есімдіктері!",
