    hub_memory_title: "Жұбын тап",
    hub_memory_desc: "Карточкаларды аударып, бірдей жұпты тап",
    memory_game_title: "Жұбын тап!",
    memory_game_sub: "Карточкаларды аударып, бірдей жұптарды тап",
    moves_label: "Қадам:",
    explain_heading: "Не істейміз?",
    speak_button: "🔊 Дауыстап оқу",
    count_explain: "Барыс сені сандар әлеміне саяхатқа шақырады! 🔢 Суретте әртүрлі заттар тұр — оларды ретімен санап шық: бір, екі, үш… Қателеспе! Санап болғасын салыстыр: қай сан үлкен, қайсысы кіші. Қаншалықты мұқият санасаң, соншалықты көп жұлдыз аласың. Жолға шығуға дайынсың ба?",
    addition_explain: "Барыстың құпиясы бар: қосу дегеніміз — екі топ затты бір топқа біріктіру! Бір қолыңда алма, екінші қолыңда да алма болса — оларды қоссаң, барлығы қанша болатынын санап шық. Екі топты да мұқият қара және көрген нәрсенің бәрін қосуды ұмытпа. Сандарды қосуға дайынсың ба?",
    subtract_explain: "Ал енді Барыс керісінше трюк көрсетеді! Азайту дегеніміз — заттардың бір бөлігі кетіп, қалғанын санауымыз. Қосу мен азайту — керісінше достар сияқты: бірі біріктіреді, екіншісі алып тастайды. Қанша зат кеткенін қара да, қалғанын санап шық. Байқап көруге дайынсың ба?",
    compare_explain: "Барыс «көп пе, аз ба» ойынын жақсы көреді! Екі санды салыстыру үшін әр топта неше зат барын санап шық, содан кейін қара — қайсысы көп, қайсысы аз. Тіпті тең болуы да мүмкін! Салыстырмас бұрын әр топты мұқият сана. Сандарды салыстыруға дайынсың ба?",
    letter_explain: "Барыс саған құпия сыбырлайды: әр әріптің өз дыбысы бар! Экрандағы үлкен әріпке қара — енді сол дыбыстан басталатын атауы бар суретті тап. Әр сөздің бірінші әрпі қалай естілетінін тыңда және Барыс көрсеткен әріппен салыстыр. Әріптерді іздеуге дайынсың ба?",
    word_explain: "Барыс саған шашылған әріптерді дайындады! Әр сөз бір-бірінің артынан ретімен тұратын әріптерден тұрады. Суретке қара — ол қандай сөз құру керектігін айтады. Толық сөз шыққанша әріптерді бірінен соң бірін бас. Сөздер құруға дайынсың ба?",
    vowel_explain: "Барыс дыбыстардың құпиясын ашады! Дауысты дыбыстар еркін айтылады, аузыңа ештеңе кедергі жасамайды — а-а-а, о-о-о! Ал дауыссыз дыбыстар кедергімен айтылады — ерін, тіс немесе тілмен, мысалы б немесе с. Әріпті тыңда да ойлан: бұл дауысты ма, дауыссыз ба? Дыбыстарды тануға дайынсың ба?",
    syllable_explain: "Барыс сөздерді қол шапалақтап бөле алады! Әр сөзді кішкентай бөлшектерге — буындарға бөлуге болады. Сөзді қолыңмен шапалақтап көр: неше рет шапалақтасаң, сонша буын! Экрандағы сөзге қара да, онда неше буын барын санап шық. Сөздерді шапалақтауға дайынсың ба?",
    hub_shapes_title: "Сызықты тап",
    hub_shapes_desc: "Нүкте, түзу, кесінді, бұрыш...",
    shapes_game_title: "Сызықты тап!",
    shapes_game_sub: "Бұл сызық немесе фигура қалай аталады? Сәйкес суретті тап",
    shapes_explain: "Барыс — нағыз геометр! Сызықтардың әртүрлі аттары бар: нүкте — бұл кішкентай нүкте ғана, түзу сызық екі жаққа да тегіс, шексіз жүреді, ал сынық сызық найзағайдай ары-бері секіреді! Атауға қара да, соған сәйкес сызықты тап. Сызықтарды үйренуге дайынсың ба?",
    hub_flatsolid_title: "Жазық па, көлемді ме?",
