    flatsolid_explain: "Барыс әртүрлі заттарды көрсетеді! Жазық фигуралар — қағаздағы сурет сияқты, олардың қалыңдығы жоқ, мысалы шеңбер немесе шаршы. Ал көлемді фигуралар — қолмен айналдыруға болатын, мысалы доп (шар) немесе текше (куб). Затқа қара да ойлан: ол жазық па, көлемді ме? Түсінуге дайынсың ба?",
