    alphabetorder_explain: "Барыс сөздікті пайдалануды үйренеді! Сөздікте сөздер алфавит бойынша орналасады — әріптер ретімен келеді: А, Б, В, Г... Екі әріпке қара да, қайсысы алфавитте бұрын келетінін тап. Дайынсың ба?",
