    reading_q4_note3: "Осы тоқсанның «Жанрларды салыстыру», «Тыныс белгілері» тақырыптары әлі жасалмады",
    hub_punctuation_title: "Қай белгі?",
    hub_punctuation_desc: "Нүкте, ? немесе !",
    punctuation_explain: "Барыс тыныс белгілерін қоюды үйренеді! Әңгіменің соңында нүкте (.) қойылады. Сұрақтың соңында — сұрау белгісі (?). Леппе соңында — леп белгісі (!). Сөйлемді оқы да, керекті белгіні тап. Дайынсың ба?",
