    hub_genre_title: "Бұл қандай жанр?",
    hub_genre_desc: "Ертегі, жұмбақ, өлең бе?",
    genre_explain: "Барыс мәтіндердің әртүрлі түрлерін ажыратуды үйренеді! Ертегінің, жұмбақтың, жаңылтпаштың, мақалдың, өлеңнің және әңгіменің — әрқайсысының өз ерекшелігі бар. Сипаттаманы оқы да, бұл қандай жанр екенін анықта. Дайынсың ба?",
