    hub_lecture_kazakh_title: "Видео-сабақ: Сәлем!",
    hub_lecture_kazakh_desc: "Алғашқы қазақша сөздер мен тіркестер",
    lecture_kazakh_video_title: "Видео-сабақ: Сәлем!",
    lecture_kazakh_explain: "Барыс сені қазақ тілі бойынша видео-сабаққа шақырады! Мұғалім қазақша қалай амандасу керектігін және атыңды қалай сұрау керектігін көрсетеді — «Сәлем! Сенің атың кім?». Сен біздің қазақша сөздер туралы ойындарымызды ойнадың, ал енді нағыз қазақша сөйлеуді естисің. Қарауға дайынсың ба?",
    hub_lecture_estestvo_title: "Видео-сабақ: өсімдік бөліктері",
    hub_lecture_estestvo_desc: "Өсімдіктер туралы толығырақ",
    lecture_estestvo_video_title: "Видео-сабақ: өсімдік бөліктері!",
    lecture_estestvo_explain: "Барыс сені жаратылыстану бойынша видео-сабаққа шақырады! Сен өсімдік бөліктері туралы біздің ойынымызды ойнадың — енді мұғалім тамыр, сабақ, жапырақ, гүл және жеміс туралы егжей-тегжейлі айтатын нағыз видео-сабақты қара. Қарауға дайынсың ба?",
    hub_lecture_digital_title: "Видео-сабақ: құрылғылар",
    hub_lecture_digital_desc: "Компьютер туралы толығырақ",
    lecture_digital_video_title: "Видео-сабақ: құрылғылар!",
    lecture_digital_explain: "Барыс сені цифрлық сауаттылық бойынша видео-сабаққа шақырады! Сен компьютер құрылғылары туралы біздің ойынымызды ойнадың — енді компьютердің не екенін және оның әртүрлі бөліктері не үшін керек екенін түсіндіретін мультфильмді қара. Қарауға дайынсың ба?",
    hub_lecture_poznanie_title: "Видео-сабақ: светофор",
    hub_lecture_poznanie_desc: "Жол қозғалысы ережелері толығырақ",
    lecture_poznanie_video_title: "Видео-сабақ: светофор!",
    lecture_poznanie_explain: "Барыс сені дүниетану бойынша видео-сабаққа шақырады! Сен жол белгілері туралы біздің ойынымызды ойнадың — енді светофор мен жол қозғалысы ережелері туралы егжей-тегжейлі айтылатын мультфильмді қара. Көшеде қауіпсіз болу үшін мұны білу өте маңызды. Қарауға дайынсың ба?",
    hub_lecture_muzyka_title: "Видео-сабақ: аспаптар",
    hub_lecture_muzyka_desc: "Музыкалық аспаптар туралы толығырақ",
    lecture_muzyka_video_title: "Видео-сабақ: аспаптар!",
    lecture_muzyka_explain: "Барыс сені музыка бойынша видео-сабаққа шақырады! Сен музыкалық аспаптар туралы біздің ойынымызды ойнадың — енді әртүрлі аспаптардың қалай дыбысталатынын көрсететін мультфильмді қара. Қарауға дайынсың ба?",
