    moves_label: "Moves:",
    explain_heading: "What are we going to do?",
    speak_button: "🔊 Read aloud",
    count_explain: "Barys invites you on a journey through numbers! 🔢 Different objects live in the picture — count them in order: one, two, three… Don't make a mistake! Once you've counted, compare: which number turned out bigger, and which is smaller. The more carefully you count, the more stars you'll earn. Ready to set off?",
    addition_explain: "Barys knows a secret: addition is when we combine two groups of objects into one! If you have apples in one hand and apples in the other — put them together and count how many there are in total. Look carefully at both groups and don't forget to add everything you see. Ready to add numbers?",
    subtract_explain: "Now Barys will show you the opposite trick! Subtraction is when part of the objects go away, and we count how many are left. Addition and subtraction are like opposite friends: one combines, the other removes. Watch how many objects disappeared, and count what remains. Ready to try?",
    compare_explain: "Barys loves playing 'bigger or smaller'! To compare two numbers, count how many objects are in each group, then look — which has more, and which has fewer. They might even be equal! Count each group carefully before comparing. Ready to compare numbers?",
    letter_explain: "Barys whispers a secret to you: every letter has its own sound! Look at the big letter on the screen — now find the picture whose name starts with that same sound. Listen to how the first letter sounds in each word, and compare it with the one Barys showed you. Ready to search for letters?",
    word_explain: "Barys has prepared scattered letters for you! Every word is made of letters that stand one after another in order. Look at the picture — it will tell you which word to build. Tap the letters one by one until you get the whole word. Ready to build words?",
    vowel_explain: "Barys reveals the secret of sounds! Vowel sounds are sung freely, nothing blocks your mouth — ah-ah-ah, oh-oh-oh! But consonant sounds are pronounced with an obstacle — your lips, teeth, or tongue, like b or s. Listen to the letter and think: is it a vowel or a consonant? Ready to solve the sounds?",
    syllable_explain: "Barys knows how to clap out words! Every word can be split into small pieces — syllables. Try clapping the word out with your hands: however many times you clap, that's how many syllables there are! Look at the word on the screen and count how many syllables it has. Ready to clap out words?",
    hub_shapes_title: "Find the Line",
    hub_shapes_desc: "Point, line, segment, angle...",
    shapes_game_title: "Find the Line!",
    shapes_game_sub: "What is this line or shape called? Find the matching picture",
    shapes_explain: "Barys is a real geometer! Lines have different names: a point is just a tiny dot, a straight line goes on evenly forever in both directions, while a broken line zigzags back and forth like lightning! Look at the name and find the matching line. Ready to study lines?",
    hub_flatsolid_title: "Flat or Solid?",
