    moves_label: "Юришлар:",
    explain_heading: "Нима қиламиз?",
    speak_button: "🔊 Овоз чиқариб ўқиш",
    count_explain: "Барыс сени сонлар саёҳатига таклиф қиляпти! 🔢 Расмда турли буюмлар бор — уларни тартиб билан сана: бир, икки, уч… Хато қилма! Санаб бўлгач, солиштир: қайси сон катта, қайсиси кичик. Қанча диққат билан санасанг, шунча кўп юлдуз оласан. Йўлга чиқишга тайёрмисан?",
    addition_explain: "Барысда бир сир бор: қўшиш — бу икки гуруҳ буюмни битта гуруҳга бирлаштириш! Бир қўлингда олма, иккинчи қўлингда ҳам олма бўлса — уларни қўшиб, жамики нечта бўлганини сана. Иккала гуруҳга ҳам диққат билан қара ва кўрганингнинг ҳаммасини қўшишни унутма. Сонларни қўшишга тайёрмисан?",
    subtract_explain: "Энди Барыс тескари фокус кўрсатади! Айириш — бу буюмларнинг бир қисми кетиб, қолганини санашимиз. Қўшиш ва айириш — тескари дўстлар каби: бири бирлаштиради, иккинчиси олиб ташлайди. Нечта буюм кетганини кўр ва қолганини сана. Синаб кўришга тайёрмисан?",
    compare_explain: "Барыс «кўп ёки кам» ўйинини яхши кўради! Икки сонни солиштириш учун ҳар гуруҳда нечта буюм борлигини сана, кейин қара — қайсисида кўп, қайсисида кам. Улар тенг ҳам бўлиши мумкин! Солиштиришдан олдин ҳар гуруҳни диққат билан сана. Сонларни солиштиришга тайёрмисан?",
    letter_explain: "Барыс сенга бир сирни шивирлайди: ҳар бир ҳарфнинг ўз товуши бор! Экрандаги катта ҳарфга қара — энди шу товушдан бошланадиган номли расмни топ. Ҳар сўзнинг биринчи ҳарфи қандай эшитилишини тингла ва Барыс кўрсатган ҳарф билан солиштир. Ҳарфларни излашга тайёрмисан?",
    word_explain: "Барыс сенга сочилган ҳарфларни тайёрлади! Ҳар сўз бир-бирининг кетидан тартиб билан турадиган ҳарфлардан иборат. Расмга қара — у қайси сўзни тузиш кераклигини айтади. Бутун сўз чиққунча ҳарфларни бирин-кетин бос. Сўз тузишга тайёрмисан?",
    vowel_explain: "Барыс товушларнинг сирини очади! Унли товушлар эркин айтилади, оғзингга ҳеч нарса тўсқинлик қилмайди — а-а-а, о-о-о! Ундош товушлар эса тўсиқ билан айтилади — лаб, тиш ёки тил билан, масалан б ёки с. Ҳарфни тингла ва ўйла: бу унлими ёки ундошми? Товушларни ечишга тайёрмисан?",
    syllable_explain: "Барыс сўзларни қарсак чалиб бўлишни билади! Ҳар сўзни кичик бўлакларга — бўғинларга бўлиш мумкин. Сўзни қўлинг билан қарсак чалиб кўр: неча марта қарсак чалсанг, шунча бўғин бор! Экрандаги сўзга қара ва унда нечта бўғин борлигини сана. Сўзларни қарсак чалишга тайёрмисан?",
    hub_shapes_title: "Чизиқни топ",
    hub_shapes_desc: "Нуқта, тўғри чизиқ, кесма, бурчак...",
    shapes_game_title: "Чизиқни топ!",
    shapes_game_sub: "Бу чизиқ ёки шакл қандай аталади? Мос расмни топ",
    shapes_explain: "Барыс — ҳақиқий геометр! Чизиқларнинг турли номлари бор: нуқта — бу кичкина нуқта, тўғри чизиқ икки томонга ҳам текис, чексиз давом этади, синиқ чизиқ эса чақмоқ каби у ёқдан-бу ёққа сакрайди! Номга қара ва унга мос чизиқни топ. Чизиқларни ўрганишга тайёрмисан?",
    hub_flatsolid_title: "Текис ёки ҳажмли?",
