    flatsolid_game_sub: "Бу буюм қоғоз каби текисми ёки тўп каби ҳажмлими?",
    flatsolid_explain: "Барыс турли буюмларни кўрсатяпти! Текис шакллар — қоғоздаги расм каби, уларнинг қалинлиги йўқ, масалан айлана ёки квадрат. Ҳажмли шакллар эса — қўлингда айлантириш мумкин бўлган, масалан тўп (шар) ёки куб. Буюмга қара ва ўйла: у текисми ёки ҳажмлими? Тушунишга тайёрмисан?",
