    addition_explain: "Барыс як сирро медонад: ҷамъ — ин вақте аст, ки мо ду гурӯҳи чизҳоро ба як гурӯҳ муттаҳид мекунем! Агар дар як дастат себ бошад ва дар дасти дигар низ себ — онҳоро якҷоя кун ва бишумор, ки ҳамааш чанд шуд. Ба ҳар ду гурӯҳ бодиққат нигоҳ кун ва фаромӯш накун, ки ҳар чи мебинӣ, ҷамъ кунӣ. Омодаи ҷамъ кардани рақамҳо ҳастӣ?",
