    compare_explain: "Барыс бозии «бештар ё камтар»-ро дӯст медорад! Барои муқоисаи ду рақам, бишумор, ки дар ҳар гурӯҳ чанд чиз ҳаст, баъд бубин — дар куҷо бештар аст, дар куҷо камтар. Шояд онҳо баробар ҳам бошанд! Пеш аз муқоиса ҳар гурӯҳро бодиққат бишумор. Омодаи муқоисаи рақамҳо ҳастӣ?",
    letter_explain: "Барыс ба ту як сирро пичиррос мезанад: ҳар ҳарф садои худро дорад! Ба ҳарфи калон дар экран нигоҳ кун — ҳоло расмеро ёб, ки номаш аз ҳамон садо оғоз мешавад. Гӯш кун, ки ҳарфи аввали ҳар калима чӣ гуна садо медиҳад ва бо он чи Барыс нишон дод муқоиса кун. Омодаи ҷустуҷӯи ҳарфҳо ҳастӣ?",
    word_explain: "Барыс барои ту ҳарфҳои пароканда омода кард! Ҳар калима аз ҳарфҳое иборат аст, ки паиҳам меистанд. Ба расм нигоҳ кун — он мегӯяд, ки кадом калимаро бояд бисозӣ. Ҳарфҳоро якто-якто пахш кун, то калимаи пурра ҳосил шавад. Омодаи сохтани калимаҳо ҳастӣ?",
    vowel_explain: "Барыс сирри садоҳоро мекушояд! Садоноки озод суруда мешавад, ба даҳонат чизе монеъ намешавад — а-а-а, о-о-о! Ҳамсадоҳо бошанд бо монеа талаффуз мешаванд — бо лаб, дандон ё забон, масалан б ё с. Ба ҳарф гӯш кун ва фикр кун: ин садонок аст ё ҳамсадо? Омодаи ҳалли садоҳо ҳастӣ?",
    syllable_explain: "Барыс мефаҳмад, ки калимаҳоро чӣ гуна бо чапак задан ҷудо кунад! Ҳар калимаро ба порчаҳои хурд — ҳиҷоҳо ҷудо кардан мумкин аст. Калимаро бо дастҳоят чапак зада бин: чанд бор чапак занӣ, ҳамон қадар ҳиҷо аст! Ба калимаи дар экран нигоҳ кун ва бишумор, ки дар он чанд ҳиҷо ҳаст. Омодаи чапак задани калимаҳо ҳастӣ?",
