    spelling_explain: "Барыс бо забони русӣ саводнок навиштанро меомӯзад! Баъд аз ҳарфҳои Ж ва Ш ҳамеша И навишта мешавад, на Ы. Баъд аз ҳарфҳои Ч ва Щ ҳамеша А навишта мешавад, на Я. Бифаҳм, ки кадом калима дуруст навишта шудааст. Омодаӣ?",
