    riddle_explain: "Барыс чистонҳоро дӯст медорад! Дар ҳар чистон як чиз пинҳон аст — бояд аломатҳоро бодиққат хонда, бифаҳмӣ, ки он чист. Чистонро хон ва расми дурустро интихоб кун. Омодаи ёфтан ҳастӣ?",
