    hub_prebukvar_desc: "Асрори забонро кушоем",
    alippe_letters1_explain: "Барыс алифбои қазоқиро (Әліппе) меомӯзад! Мувофиқи усули Аҳмет Байтурсинов, аввал овозҳои бештар вохӯрдашаванда таълим дода мешаванд: а, р, л, н. Ба расм нигоҳ кун ва бифаҳм, ки номи он бо кадом ҳарф сар мешавад. Омодаи омӯхтани алифбо ҳастӣ?",
